/**
 * The world does not wait.
 *
 * Every season, each faction acts on its own schedule regardless of whether the
 * player did anything. This is the module that makes the game a simulation
 * rather than a choose-your-own-adventure: sit still in 新野 for five years and
 * Cao Cao still unifies the north, Liu Biao still dies, Liu Cong still
 * surrenders, and the cavalry still arrives.
 *
 * Two properties matter for the "扮演" mode:
 *
 *   · Faction behaviour is driven by POWER RATIOS and SEASON, not by scripted
 *     events. A player who weakens Cao Cao early therefore faces a weaker Cao
 *     Cao later — the world responds to the deviation instead of resetting to
 *     the historical script.
 *   · The player's absence is not special. There is no "if player is in 荆州"
 *     branch here; the same rules run, and the player simply may or may not be
 *     standing in the way.
 *
 * All of it is deterministic given (state, season), so a replay reproduces the
 * same world.
 */

import { rollDie, pickOne } from './rng.js'

/**
 * Faction roster for the playable window (184–223). `power` is a 0..100 scalar
 * of field armies + secure territory; it is the only quantity the AI reasons
 * about, on purpose — a richer model would need far more data than the save
 * carries and would be unauditable.
 */
export const INITIAL_FACTIONS = {
  liubei: { name: '刘备', power: 3, seat: 'zhuojun', holds: [], stance: {}, from: 184 },
  caocao: { name: '曹操', power: 16, seat: 'chenliu', home: 'yanzhou', holds: ['yanzhou'], stance: {}, from: 184 },
  yuanshao: { name: '袁绍', power: 26, seat: 'ye', home: 'jizhou', holds: ['jizhou'], stance: {}, from: 184 },
  gongsunzan: { name: '公孙瓒', power: 18, seat: 'ji', home: 'youzhou', holds: ['youzhou'], stance: {}, from: 184 },
  taoqian: { name: '陶谦', power: 12, seat: 'xiapi', home: 'xuzhou', holds: ['xuzhou'], stance: {}, from: 184 },
  lvbu: { name: '吕布', power: 10, seat: 'puyang', home: '', holds: [], stance: {}, from: 192, to: 198 },
  liubiao: { name: '刘表', power: 22, seat: 'xiangyang', home: 'jingzhou', holds: ['jingzhou'], stance: {}, from: 190 },
  sunquan: { name: '孙权', power: 14, seat: 'wu', home: 'yangzhou', holds: ['yangzhou'], stance: {}, from: 200 },
  liuzhang: { name: '刘璋', power: 16, seat: 'chengdu', home: 'yizhou', holds: ['yizhou'], stance: {}, from: 194 },
  zhanglu: { name: '张鲁', power: 9, seat: 'hanzhong', home: 'hanzhong', holds: ['hanzhong'], stance: {}, from: 191 },
  dongzhuo: { name: '董卓', power: 30, seat: 'luoyang', home: 'sili', holds: ['sili'], stance: {}, from: 184, to: 192 }
}

/**
 * Which provinces border which.
 *
 * Conquest requires adjacency. Without this table the world produces
 * geographically impossible results — 袁绍 taking 益州 in 185 across four
 * provinces he never crossed — and the whole simulation reads as noise. This is
 * coarse on purpose: eleven nodes, the corridors that actually mattered.
 */
export const ADJACENCY = {
  sili: ['yanzhou', 'yuzhou', 'jingzhou', 'hanzhong', 'jizhou'],
  yanzhou: ['sili', 'jizhou', 'qingzhou', 'yuzhou', 'xuzhou'],
  yuzhou: ['sili', 'yanzhou', 'xuzhou', 'jingzhou'],
  jizhou: ['yanzhou', 'qingzhou', 'youzhou', 'sili'],
  qingzhou: ['jizhou', 'yanzhou', 'xuzhou', 'youzhou'],
  youzhou: ['jizhou', 'qingzhou'],
  xuzhou: ['yanzhou', 'yuzhou', 'qingzhou', 'yangzhou', 'jingzhou'],
  jingzhou: ['sili', 'yuzhou', 'xuzhou', 'yangzhou', 'yizhou'],
  yangzhou: ['xuzhou', 'jingzhou'],
  yizhou: ['jingzhou', 'hanzhong'],
  hanzhong: ['sili', 'yizhou']
}

/** True when a faction exists on the map in this year. */
export function isActive(faction, year) {
  if (faction === undefined || faction === null) return false
  if (Number.isFinite(faction.from) && year < faction.from) return false
  if (Number.isFinite(faction.to) && year > faction.to) return false
  return true
}

/** Base growth each faction gets per season, before modifiers. */
const GROWTH = {
  caocao: 0.55,
  yuanshao: 0.5,
  sunquan: 0.45,
  liubiao: 0.15,
  liuzhang: 0.1,
  gongsunzan: -0.35,
  taoqian: -0.25,
  lvbu: -0.5,
  zhanglu: 0.05,
  dongzhuo: -0.9,
  liubei: 0
}

/**
 * Seasonal drift: strong factions consolidate, weak ones erode. This is what
 * produces the historical shape without scripting any of it — 袁绍 grows early
 * and then stalls once his power passes ~70 (his historical ceiling), 公孙瓒
 * bleeds out, 董卓 collapses after the capital burns.
 */
function seasonalGrowth(factionId, power) {
  const base = GROWTH[factionId] ?? 0
  if (base === 0) return 0
  // Diminishing returns above 70: an over-mighty faction stops compounding.
  const ceiling = 70
  if (base > 0 && power >= ceiling) {
    return Math.max(0, base * ((100 - power) / (100 - ceiling)) * 0.3)
  }
  return base
}

/**
 * Advance every faction one season.
 *
 * Order matters and is deliberate: growth first, then at most one conquest, then
 * ONE chronicle line per faction describing where it ended up. Emitting a line
 * per delta produced two or three lines for the same faction in the same year
 * whenever a conquest bumped its power over a band boundary, which reads as a
 * stutter rather than as history.
 *
 * @param {object} state mutable save
 * @returns {{ state: object, events: Array<{faction:string, kind:string, text:string}> }}
 */
export function advanceFactions(state) {
  // Deep clone before mutating. The faction table is reachable from the save
  // object, so editing it in place would make `advanceWorld(state)` and
  // `advanceWorld(state)` (same input) produce different futures — which breaks
  // replay and would let a client reroll the world by re-calling the tool.
  const factions = JSON.parse(JSON.stringify(state.factions ?? INITIAL_FACTIONS))
  const year = Number.isFinite(state?.clock?.year) ? state.clock.year : 184
  let rng = state.rng

  // A warlord who has LEFT the stage does not keep his provinces: 董卓 dead in
  // 192 must not still hold 司隶 in 200. His lands become unowned and whoever
  // borders them can take them.
  //
  // Note the `year > faction.to` test rather than `!isActive`: a faction that
  // has not STARTED yet (刘表 before 190) must keep its provinces so that it
  // appears at full strength on schedule. Treating "not yet active" as "expired"
  // silently deleted 刘表's 荆州 before he ever arrived.
  for (const id of Object.keys(factions)) {
    const faction = factions[id]
    if (id === 'liubei') continue
    if (Number.isFinite(faction.to) && year > faction.to && faction.holds?.length > 0) {
      faction.holds = []
      faction.power = 0
    }
  }

  const before = {}
  for (const id of Object.keys(factions)) {
    before[id] = Number.isFinite(factions[id].power) ? factions[id].power : 0
  }

  for (const id of Object.keys(factions)) {
    if (id === 'liubei') {
      // The player's own power is never grown by the engine: it changes only
      // through the player's actions. Letting the world buff the player would
      // quietly turn this into an idle game.
      continue
    }
    const faction = factions[id]
    if (faction.power <= 0) continue

    // Power is land, troops and grain. A warlord who holds no province is not a
    // warlord: he becomes a wandering commander, which is exactly what happened
    // to 吕布 and, for twenty years, to 刘备. Without this the map fills with
    // powerful landless ghosts that can never be attacked and never leave.
    //
    // Checked BEFORE the era gate on purpose: a faction outside its era window
    // with no land must still decay. (Skipping the whole block for inactive
    // factions left 吕布 at full strength for eight years before he appeared.)
    const landless = !Array.isArray(faction.holds) || faction.holds.length === 0
    if (landless) {
      faction.power = Math.round(faction.power * 0.55 * 10) / 10
      continue
    }
    if (!isActive(faction, year)) continue

    const jitterRolled = rollDie(rng, 5)
    rng = jitterRolled.state
    const jitter = jitterRolled.value - 3
    const delta = seasonalGrowth(id, faction.power) + jitter * 0.25
    faction.power = Math.round(Math.min(100, Math.max(0, faction.power + delta)) * 10) / 10
  }

  const events = []
  const opportunistic = pickOpportunity(factions, rng, year)
  rng = opportunistic.state
  if (opportunistic.event !== null) {
    events.push(opportunistic.event)
  }

  // ONE line per faction, and only when it crossed a five-point band.
  //
  // A faction grows about a point a season, so a per-season threshold either
  // fires every season (unreadable log) or never fires at all. Band crossings
  // give roughly one line a year per moving faction — the rate at which a
  // chronicle would mention it.
  for (const id of Object.keys(factions)) {
    if (id === 'liubei') continue
    const faction = factions[id]
    if (!isActive(faction, year)) continue
    const bandBefore = Math.floor(before[id] / 5)
    const bandAfter = Math.floor(faction.power / 5)
    if (bandAfter === bandBefore) continue
    if (opportunistic.event !== null && opportunistic.event.faction === id) continue
    events.push({
      faction: id,
      kind: bandAfter > bandBefore ? 'rise' : 'decline',
      text: bandAfter > bandBefore
        ? `${faction.name}之势渐盛（${bandBefore * 5} → ${bandAfter * 5}）`
        : `${faction.name}之势渐衰（${bandBefore * 5} → ${bandAfter * 5}）`
    })
  }

  return { state: { ...state, factions, rng }, events }
}

/**
 * Pick at most one "someone takes something" event.
 *
 * Three gates, all necessary:
 *   · both factions must exist in this year (no 孙权 in 185);
 *   · the strong faction must actually border the province it takes
 *     (no 袁绍 marching to 益州 in one season);
 *   · the power ratio must be lopsided enough for the move to be plausible.
 *
 * Without all three the world produces confident nonsense, and a player who
 * knows the period reads it as a bug rather than as a simulation.
 */
function pickOpportunity(factions, rng, year) {
  const candidates = []
  const ids = Object.keys(factions)
  for (const strongId of ids) {
    const strong = factions[strongId]
    if (strongId === 'liubei') continue
    if (!isActive(strong, year)) continue
    if (!Array.isArray(strong.holds) || strong.holds.length === 0) continue
    for (const weakId of ids) {
      if (weakId === strongId || weakId === 'liubei') continue
      const weak = factions[weakId]
      if (!isActive(weak, year)) continue
      if (!Array.isArray(weak.holds) || weak.holds.length === 0) continue
      // A faction's HOME province is where it actually lives: its capital is
      // defended far harder than a march. Without this a strong neighbour eats
      // everyone's capital in the first decade and the map is decided before the
      // player reaches 徐州.
      //
      // NB: `seat` is a CITY (ye, xiapi), `holds` are PROVINCES (jizhou, xuzhou).
      // Comparing them directly silently disabled this rule entirely.
      const isSeat = (province) => province === weak.home
      const required = (province) => (isSeat(province) ? 3.6 : 2.4)
      for (const province of weak.holds) {
        if (strong.power < weak.power * required(province)) continue
        const adjacent = ADJACENCY[province] ?? []
        const touches = strong.holds.some((held) => adjacent.includes(held))
        if (!touches) continue
        candidates.push({ strongId, weakId, province })
      }
    }
  }
  if (candidates.length === 0) {
    return { state: rng, event: null }
  }
  // Conquest is RARE. One per season produced six territorial changes in the
  // first twelve years, which is roughly triple the historical rate and turns
  // the map into soup. One-in-three keeps it to a change every year or two.
  const gate = rollDie(rng, 3)
  rng = gate.state
  if (gate.value !== 1) {
    return { state: rng, event: null }
  }
  const picked = pickOne(rng, candidates)
  const { strongId, weakId, province } = picked.value
  const strong = factions[strongId]
  const weak = factions[weakId]
  weak.holds = weak.holds.filter((held) => held !== province)
  strong.holds = [...strong.holds, province]
  strong.power = Math.min(100, strong.power + 3)
  weak.power = Math.max(0, weak.power - 3)
  return {
    state: picked.state,
    event: {
      faction: strongId,
      kind: 'conquest',
      text: `${strong.name}取${placeLabel(province)}于${weak.name}之手`
    }
  }
}

const PLACE_LABELS = {
  sili: '司隶',
  yanzhou: '兖州',
  jizhou: '冀州',
  youzhou: '幽州',
  xuzhou: '徐州',
  jingzhou: '荆州',
  yangzhou: '扬州',
  yizhou: '益州',
  qingzhou: '青州',
  yuzhou: '豫州',
  hanzhong: '汉中'
}

export function placeLabel(id) {
  return PLACE_LABELS[id] ?? id
}

/**
 * How much stronger is `a` than `b`, as a check modifier for the player.
 *
 * Used when the player attempts something against a faction: trying to bluff
 * Cao Cao at power 30 when you are at power 3 is not impossible, it is hard.
 * The modifier is bounded so a huge gap is a steep climb, not a wall.
 */
export function powerModifier(playerPower, targetPower) {
  const mine = Number.isFinite(playerPower) ? playerPower : 0
  const theirs = Number.isFinite(targetPower) ? targetPower : 0
  const gap = theirs - mine
  const scaled = Math.round(gap * 0.6)
  return Math.max(-35, Math.min(35, -scaled))
}

/** Sum of the player's holdings, for the digest. */
export function playerPower(state) {
  return Number.isFinite(state?.factions?.liubei?.power) ? state.factions.liubei.power : 0
}

/**
 * Sync the player's faction entry from the player's own resources.
 *
 * Kept explicit rather than derived on read so the world AI sees a consistent
 * number: the player's power is troops plus a reputation term, and fame is what
 * lets a small army punch above its weight.
 */
export function syncPlayerFaction(state) {
  const factions = state.factions ?? INITIAL_FACTIONS
  const troops = Number(state?.player?.resources?.troops) || 0
  const fame = Number(state?.player?.counters?.fame) || 0
  const holdings = Array.isArray(factions.liubei?.holds) ? factions.liubei.holds.length : 0
  const power = Math.round((Math.log10(1 + troops) * 18 + fame * 0.25 + holdings * 6) * 10) / 10
  return {
    ...state,
    factions: {
      ...factions,
      liubei: {
        ...factions.liubei,
        power,
        seat: state.place ?? factions.liubei?.seat ?? 'zhuojun'
      }
    }
  }
}
